Cs=[D1C,D2C,np.array([[0,0,1],[0,0,0],[1,1,1]]),D4C,D5C,D6C,np.array([[0,0,0],[0,0,1],[1,0,1]]),np.array([[1,1,0],[0,1,1],[1,1,0]])]
sol=[]
for a in range(-2,3):
 for b in range(-2,3):
  for c in range(-2,3):
   for d in range(-2,3):
